package com.delivery.platform.catalog.product.api;
import com.delivery.platform.catalog.common.CatalogSupport;import com.delivery.platform.common.ApiException;import com.delivery.platform.common.PageResponse;import com.delivery.platform.identity.security.IdentityPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.http.HttpStatus;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;import java.math.*;import java.text.Normalizer;import java.util.*;
@RestController public class ProductController {private final JdbcClient db;private final CatalogSupport support;public ProductController(JdbcClient d,CatalogSupport s){db=d;support=s;}public record Product(UUID id,UUID merchantId,UUID categoryId,String sku,String slug,String name,String description,String productType,BigDecimal basePrice,String currency,boolean trackInventory,BigDecimal stockQuantity,boolean available,boolean featured,String status){}public record Save(UUID categoryId,String sku,String slug,@NotBlank String name,String description,@Pattern(regexp="SIMPLE|VARIABLE|COMBO|SERVICE")String productType,@NotNull @DecimalMin("0")BigDecimal basePrice,@Pattern(regexp="[A-Z]{3}")String currency,boolean trackInventory,@DecimalMin("0")BigDecimal stockQuantity,boolean available,boolean featured){}
 @GetMapping("/api/v1/merchants/{merchantId}/products") @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_VIEW')") PageResponse<Product> list(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID merchantId,@RequestParam(defaultValue="")String search,@RequestParam(required=false)String status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){support.merchant(p,merchantId);int z=Math.min(Math.max(size,1),100),current=Math.max(page,0);String where=" from products where tenant_id=:t and merchant_id=:m and (:q='' or lower(name||' '||coalesce(sku,'')) like lower('%'||:q||'%')) and (cast(:s as varchar) is null or status=:s)";var rows=db.sql("select *"+where+" order by created_at desc limit :z offset :o").param("t",p.tenantId()).param("m",merchantId).param("q",search).param("s",status).param("z",z).param("o",current*z).query((r,n)->map(r)).list();long total=db.sql("select count(*)"+where).param("t",p.tenantId()).param("m",merchantId).param("q",search).param("s",status).query(Long.class).single();return PageResponse.of(rows,current,z,total);}
 @PostMapping("/api/v1/merchants/{merchantId}/products") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_CREATE')") Product create(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID merchantId,@Valid @RequestBody Save q){support.merchant(p,merchantId);category(p,merchantId,q.categoryId());UUID id=UUID.randomUUID();String slug=slug(q.slug()==null||q.slug().isBlank()?q.name():q.slug());try{db.sql("insert into products(id,tenant_id,merchant_id,category_id,sku,slug,name,description,product_type,base_price,currency,track_inventory,stock_quantity,available,featured) values(:i,:t,:m,:c,:s,:g,:n,:d,:y,:p,:u,:r,:q,:a,:f)").param("i",id).param("t",p.tenantId()).param("m",merchantId).param("c",q.categoryId()).param("s",q.sku()).param("g",slug).param("n",q.name()).param("d",q.description()).param("y",q.productType()).param("p",q.basePrice()).param("u",q.currency()).param("r",q.trackInventory()).param("q",q.stockQuantity()).param("a",q.available()).param("f",q.featured()).update();}catch(org.springframework.dao.DataIntegrityViolationException e){throw support.conflict("DUPLICATE_SLUG","El slug o SKU ya existe en este comercio");}support.audit(p,"PRODUCT_CREATED","PRODUCT",id);return one(p,id);}
 @GetMapping("/api/v1/products/{id}") @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_VIEW')") Product one(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){support.product(p,id);return db.sql("select * from products where id=:i").param("i",id).query((r,n)->map(r)).single();}
 @PutMapping("/api/v1/products/{id}") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_UPDATE')") Product update(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id,@Valid @RequestBody Save q){Product old=one(p,id);category(p,old.merchantId(),q.categoryId());db.sql("update products set category_id=:c,sku=:s,slug=:g,name=:n,description=:d,product_type=:y,base_price=:p,currency=:u,track_inventory=:r,stock_quantity=:q,available=:a,featured=:f,updated_at=now() where id=:i").param("c",q.categoryId()).param("s",q.sku()).param("g",slug(q.slug()==null?q.name():q.slug())).param("n",q.name()).param("d",q.description()).param("y",q.productType()).param("p",q.basePrice()).param("u",q.currency()).param("r",q.trackInventory()).param("q",q.stockQuantity()).param("a",q.available()).param("f",q.featured()).param("i",id).update();support.audit(p,"PRODUCT_UPDATED","PRODUCT",id);return one(p,id);}
 @PostMapping("/api/v1/products/{id}/publish") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_PUBLISH')") Product publish(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){Product x=one(p,id);if(!x.available()||x.basePrice().signum()<0||("VARIABLE".equals(x.productType())&&db.sql("select count(*) from product_variants where product_id=:i and active and available").param("i",id).query(Integer.class).single()==0))throw new ApiException(HttpStatus.CONFLICT,"PRODUCT_CANNOT_BE_PUBLISHED","Completa precio, disponibilidad y al menos una variante disponible");return state(p,id,"PUBLISHED","PRODUCT_PUBLISHED");}
 @PostMapping("/api/v1/products/{id}/unpublish") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_PUBLISH')") Product unpublish(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return state(p,id,"UNPUBLISHED","PRODUCT_UNPUBLISHED");}@PostMapping("/api/v1/products/{id}/archive") @Transactional @PreAuthorize("hasAuthority('CATALOG_PRODUCTS_ARCHIVE')") Product archive(@AuthenticationPrincipal IdentityPrincipal p,@PathVariable UUID id){return state(p,id,"ARCHIVED","PRODUCT_ARCHIVED");}
 private Product state(IdentityPrincipal p,UUID id,String state,String event){support.product(p,id);db.sql("update products set status=:s,updated_at=now() where id=:i").param("s",state).param("i",id).update();support.audit(p,event,"PRODUCT",id);return one(p,id);}private void category(IdentityPrincipal p,UUID merchant,UUID category){if(category==null)return;int n=db.sql("select count(*) from categories where id=:c and tenant_id=:t and merchant_id=:m and active").param("c",category).param("t",p.tenantId()).param("m",merchant).query(Integer.class).single();if(n==0)throw new ApiException(HttpStatus.BAD_REQUEST,"INVALID_CATEGORY","La categoría debe pertenecer al mismo comercio");}private String slug(String s){return Normalizer.normalize(s,Normalizer.Form.NFD).replaceAll("\\p{M}","").toLowerCase().replaceAll("[^a-z0-9]+","-").replaceAll("(^-|-$)","");}private Product map(java.sql.ResultSet r)throws java.sql.SQLException{return new Product(r.getObject("id",UUID.class),r.getObject("merchant_id",UUID.class),r.getObject("category_id",UUID.class),r.getString("sku"),r.getString("slug"),r.getString("name"),r.getString("description"),r.getString("product_type"),r.getBigDecimal("base_price"),r.getString("currency"),r.getBoolean("track_inventory"),r.getBigDecimal("stock_quantity"),r.getBoolean("available"),r.getBoolean("featured"),r.getString("status"));}}
